import{_ as d,o as e,c as o,a7 as c}from"./chunks/framework.B5H0CmYR.js";const h=JSON.parse('{"title":"일상 운영","description":"","frontmatter":{"title":"일상 운영","outline":[2,3]},"headers":[],"relativePath":"ops/operations.md","filePath":"ops/operations.md"}'),r={name:"ops/operations.md"};function a(s,t,n,g,i,l){return e(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="일상-운영" tabindex="-1">일상 운영 <a class="header-anchor" href="#일상-운영" aria-label="Permalink to &quot;일상 운영&quot;">​</a></h1><p>gaea.sh 운영 명령, 웹 운영 콘솔, 외부 AI 에이전트(MCP) 연결 설정, 문제 해결.</p><h2 id="_1-일상-운영" tabindex="-1">1. 일상 운영 <a class="header-anchor" href="#_1-일상-운영" aria-label="Permalink to &quot;1. 일상 운영&quot;">​</a></h2><p>기동·정지·재기동·로그는 <code>gaea.sh</code> 래퍼로 합니다. 브라우저로 같은 일을 하는 웹 운영 콘솔도 있으며, 제품 자체의 어드민 콘솔과는 역할이 나뉩니다. 외부 AI 에이전트(MCP) 접속면도 그 어드민 콘솔에서 켭니다.</p><h3 id="_1-1-gaea-sh-—-일상-운영-래퍼" tabindex="-1">1-1 gaea.sh — 일상 운영 래퍼 <a class="header-anchor" href="#_1-1-gaea-sh-—-일상-운영-래퍼" aria-label="Permalink to &quot;1-1 gaea.sh — 일상 운영 래퍼&quot;">​</a></h3><p><code>docker compose</code> 를 직접 입력하면 아래 세 가지 실수를 매번 직접 피해야 합니다. 또 1.3.0 번들은 루트에 compose 파일이 없고 모두 <code>system/</code> 에 있습니다. 아래 표 오른쪽 열의 원시 명령은 번들 루트에서 <code>./gaea.sh compose …</code> 로 같은 인자를 주어 실행합니다(오버레이·이미지 태그·프로젝트 디렉터리는 래퍼가 맞춥니다).</p><ul><li><code>--no-build</code> 누락</li><li><code>restart</code> 와 <code>up -d</code> 혼동</li><li><code>edge</code> 재기동 누락으로 인한 전면 502</li></ul><p>래퍼는 이 세 가지를 자동으로 처리합니다.</p><p><strong>표 1-1 gaea.sh 서브커맨드</strong></p><table tabindex="0"><thead><tr><th>명령</th><th>하는 일</th><th>동일한 원시 명령</th></tr></thead><tbody><tr><td><code>./gaea.sh start</code></td><td>기동</td><td><code>docker compose up -d --no-build</code></td></tr><tr><td><code>./gaea.sh stop</code></td><td>정지(컨테이너·볼륨 보존)</td><td><code>docker compose stop</code></td></tr><tr><td><code>./gaea.sh restart</code></td><td><strong><code>.env</code> 반영 재기동</strong></td><td><code>docker compose up -d --no-build &amp;&amp; docker compose restart edge</code></td></tr><tr><td><code>./gaea.sh status</code></td><td>상태 + 비정상 컨테이너 지목</td><td><code>docker compose --profile demo ps -a</code></td></tr><tr><td><code>./gaea.sh logs [서비스]</code></td><td>로그(기본 <code>server</code>, <code>-f</code> 팔로우)</td><td><code>docker compose --profile demo logs --tail 200 &lt;서비스&gt;</code></td></tr><tr><td><code>./gaea.sh down</code></td><td>컨테이너 삭제(확인 필요, 볼륨 보존)</td><td><code>docker compose down</code></td></tr><tr><td><code>./gaea.sh logs --boot [서비스]</code></td><td>로그 <strong>전체</strong>에서 부팅 표식 줄(<code>[ha]</code>·<code>[bootstrap]</code>·<code>[credentials]</code>·<code>[migrate]</code>·<code>[license]</code>)만 — 200줄 밖으로 밀려난 것도 찾습니다</td><td><code>docker compose logs --no-color server | grep -E …</code></td></tr><tr><td><code>./gaea.sh backup [--dir &lt;디렉터리&gt;]</code></td><td>정지 백업 — server·edge 가 기동 중이면 거절(번들 PG 의 <code>meta-postgres</code> 는 예외 — 오히려 healthy 까지 올립니다). 아카이브 0600</td><td>이미지 내 CLI(<code>dist/scripts/backup.js</code>) 호출</td></tr><tr><td><code>./gaea.sh restore [--dir &lt;디렉터리&gt;] [--yes] &lt;아카이브&gt;</code></td><td>복원 — <strong>현재 DB를 덮어씁니다</strong>. 메타DB 가 PG 면 계획(<code>--dry-run</code>)을 보여 주고 <code>yes</code> 를 받습니다(<code>--yes</code> 를 주면 확인을 생략합니다)</td><td>이미지 내 CLI(<code>dist/scripts/backup-restore.js</code>) 호출</td></tr><tr><td><code>./gaea.sh console [--port &lt;포트&gt;]</code></td><td>웹 운영 콘솔 기동</td><td><code>system/console.sh ops</code> 와 같습니다</td></tr><tr><td><code>./gaea.sh compose &lt;인자…&gt;</code></td><td>래퍼와 같은 compose 해석(오버레이·태그·프로젝트 디렉터리)으로 <code>docker compose &lt;인자…&gt;</code> 실행</td><td><code>docker compose --project-directory . -f system/docker-compose.yml …</code></td></tr><tr><td><code>./gaea.sh pg-migrate [--dry-run|--yes]</code></td><td>SQLite → PostgreSQL 메타DB 이관(서버 정지 상태에서만 — 2-2)</td><td>이미지 내 CLI(<code>dist/scripts/migrate-sqlite-to-pg.js</code>) 호출</td></tr></tbody></table><p>명령과 옵션은 <code>./gaea.sh --help</code> 로 봅니다. 온프렘 스크립트의 도움말은 모두 man 페이지 꼴(NAME · SYNOPSIS · DESCRIPTION · OPTIONS/COMMANDS · ENVIRONMENT · EXAMPLES · EXIT STATUS · SEE ALSO)이고, 터미널 화면보다 길면 페이저(<code>PAGER</code>, 기본 <code>less -R</code>)로 넘깁니다.</p><h4 id="설치·점검을-돕는-명령" tabindex="-1">설치·점검을 돕는 명령 <a class="header-anchor" href="#설치·점검을-돕는-명령" aria-label="Permalink to &quot;설치·점검을 돕는 명령&quot;">​</a></h4><p><strong>표 1-2 gaea.sh 도우미 명령(2026-10-07)</strong></p><table tabindex="0"><thead><tr><th>명령</th><th>하는 일</th></tr></thead><tbody><tr><td><code>./gaea.sh preflight</code></td><td>사전 점검 — docker·compose v2 · 포트(80/443) · 디스크 여유(2 GB 미만 실패, 10 GB 미만 경고) · 접속 주소 DNS · PostgreSQL(접속·인증·CREATE 권한·버전 14 이상·시계 차 2초) · HA 공유 볼륨(uid 1000 쓰기·노드 표식). 결과는 <code>[ok]</code>/<code>[경고]</code>/<code>[실패]</code> 한 줄 + <code>→ 조치:</code>. 실패가 있으면 종료코드 1. 설치 마법사가 <code>.env</code> 를 쓰기 전에 자동으로 돌립니다</td></tr><tr><td><code>./gaea.sh tls status</code></td><td>인증서 점검 — 주체·발급자 · SAN 이 접속 주소를 덮는가 · 키 짝 · 체인 · 남은 일수(30일 이내 경고 · 7일 이내 위험 · 만료 실패)</td></tr><tr><td><code>./gaea.sh tls csr [--san 이름1,이름2]</code></td><td>사내 CA 에 낼 발급 요청서(CSR) + 개인키를 <code>certs/request-&lt;시각&gt;/</code> 에 만듭니다. 이름은 <code>APP_BASE_URL</code> 의 호스트이며 SAN 에 자동으로 들어갑니다</td></tr><tr><td><code>./gaea.sh tls install &lt;인증서&gt; &lt;개인키&gt; [&lt;체인&gt;]</code></td><td>검사 → 옛 것 <code>certs/backup-&lt;시각&gt;/</code> 보관 → 배치 → edge <code>nginx -s reload</code>(접속 끊김 없음) → 포트에서 새 인증서 대조. 검사 실패면 배치하지 않고, <code>nginx -t</code> 실패면 옛 인증서로 되돌립니다</td></tr><tr><td><code>./gaea.sh tls selfsigned [--renew] [--force]</code></td><td>자체서명(825일) 생성·갱신. CA 발급본은 <code>--force</code> 없이 덮지 않습니다</td></tr><tr><td><code>./gaea.sh tls check &lt;인증서&gt; &lt;개인키&gt;</code></td><td>배치하지 않고 검사만(설치 마법사의 「인증서 검사」 버튼이 씁니다). 공통 옵션 <code>--dir</code> · <code>--host</code> · <code>--no-apply</code></td></tr><tr><td><code>./gaea.sh keys export [--out &lt;파일&gt;] [--encrypt]</code></td><td>키 복구 시트(0600) — 데이터소스 암호화 키·백업 암호화 키(+<code>_PREVIOUS</code>)·번들 PG 비밀번호·SSO 서명키의 값과 지문(SHA-256 앞 16자). 화면에는 지문만. 서버 밖으로 옮기고 서버에서는 <code>shred -u</code> 로 지웁니다. <code>--encrypt</code> 는 12자 이상 암호로 잠근 <code>.enc</code></td></tr></tbody></table><blockquote><p><strong>주의</strong> <code>./gaea.sh restart</code> 는 <code>docker compose restart</code> 와 <strong>다릅니다</strong>. <code>docker compose restart</code> 는 같은 컨테이너를 다시 띄울 뿐이라 바뀐 <code>.env</code> 를 읽지 않습니다. <code>.env</code> 를 고친 뒤에는 반드시 <code>./gaea.sh restart</code>(컨테이너 재생성 + edge 재기동)를 씁니다.</p></blockquote><h4 id="backup-·-restore-가-이-래퍼에-있는-이유" tabindex="-1">backup · restore 가 이 래퍼에 있는 이유 <a class="header-anchor" href="#backup-·-restore-가-이-래퍼에-있는-이유" aria-label="Permalink to &quot;backup · restore 가 이 래퍼에 있는 이유&quot;">​</a></h4><p>두 명령은 compose 오버레이(jdbc·pg·ha)와 이미지 태그가 정확히 지정돼야 올바른 인스턴스를 대상으로 동작합니다. 래퍼가 이 지정을 맡으므로, 백업·복원도 래퍼로 실행합니다. 오버레이를 하나라도 빠뜨리면 다른 인스턴스를 백업할 수 있습니다.</p><h3 id="_1-2-웹-운영-콘솔" tabindex="-1">1-2 웹 운영 콘솔 <a class="header-anchor" href="#_1-2-웹-운영-콘솔" aria-label="Permalink to &quot;1-2 웹 운영 콘솔&quot;">​</a></h3><p>브라우저에서 일상 운영·정지 백업·복원·복구 리허설을 수행합니다.</p><p>실행 주체는 여전히 호스트의 <code>gaea.sh</code>·<code>restore-rehearsal.sh</code> 이고, 웹 계층에는 docker 소켓이 없습니다.</p><p><strong>표 1-3 화면 구성 6개 섹션</strong></p><table tabindex="0"><thead><tr><th>섹션</th><th>내용</th></tr></thead><tbody><tr><td>사전 점검</td><td>docker · compose · <code>.env</code> · 래퍼 존재 여부</td></tr><tr><td>상태·수명주기</td><td>합본 카드 — 상태 확인 · 기동 · 정지 · 재기동 버튼</td></tr><tr><td>로그</td><td>서비스별 최근 200줄. 실시간 따라보기(<code>-f</code>)는 없습니다 — 작업이 끝나지 않아 다른 작업을 막기 때문입니다</td></tr><tr><td>백업·복원·복구 리허설</td><td>합본 카드 — 정지 백업, 아카이브 선택 후 이중 확인 복원, 복구 시간(RTO) 측정</td></tr><tr><td>실행</td><td>진행 중 작업의 단계·로그 실시간 스트림</td></tr><tr><td>작업 이력</td><td>이 콘솔 세션에서 실행한 작업 기록</td></tr></tbody></table><h4 id="보안" tabindex="-1">보안 <a class="header-anchor" href="#보안" aria-label="Permalink to &quot;보안&quot;">​</a></h4><ul><li>이 서버 안에서만 접속 — <code>127.0.0.1:9320</code></li><li>일회성 토큰 — 기동할 때 접속 링크에 담아 한 번만 출력합니다</li><li>쿠키를 쓰지 않고 다른 사이트에서 오는 요청(CORS)을 모두 거부합니다</li><li><strong>작업 잠금</strong> — 한 번에 1건만 실행하고, 두 번째 요청은 <code>409</code> 로 거부합니다</li><li>30분 동안 쓰지 않으면 스스로 종료합니다</li><li>원격 접속은 SSH 로컬 포워딩 — <code>ssh -L 9320:127.0.0.1:9320 &lt;계정&gt;@&lt;서버&gt;</code></li></ul><blockquote><p><strong>참고</strong> <code>./gaea.sh down</code>(컨테이너 삭제)은 이 화면에 <strong>없습니다</strong>. 되돌릴 수 없는 작업을 버튼 하나로 실행하지 않도록 뺐습니다. 필요하면 터미널에서 직접 실행합니다.</p></blockquote><blockquote><p><strong>그림 1-1</strong> 웹 운영 콘솔. 상단에 온라인 백업과의 역할 분담 안내가 항상 표시되고, 복원 카드에는 「복원은 데이터 볼륨의 현재 DB 를 덮어씁니다 — 되돌릴 수 없습니다.」 경고와 이중 확인(체크박스 + 아카이브 파일명 재입력)이 있습니다. 상세는 「복구 › 1-3 웹 콘솔의 이중 확인」.</p></blockquote><h3 id="_1-3-어드민-콘솔과의-역할-분담" tabindex="-1">1-3 어드민 콘솔과의 역할 분담 <a class="header-anchor" href="#_1-3-어드민-콘솔과의-역할-분담" aria-label="Permalink to &quot;1-3 어드민 콘솔과의 역할 분담&quot;">​</a></h3><blockquote><p><strong>참고</strong> 제품이 살아 있을 때 <strong>온라인 백업의 주 수단은 어드민 콘솔</strong>입니다. 웹 운영 콘솔의 정지 백업은 <strong>서버를 내려야 하는</strong> 백업이며, 업그레이드·이설처럼 정지가 전제인 상황과 제품이 뜨지 않아 어드민 콘솔에 들어갈 수 없는 상황을 위한 것입니다.</p></blockquote><p>어드민 콘솔(제품 자체, <code>/admin</code>)은 운영 콘솔과 다른 화면이지만 운영과 맞닿아 있습니다. 「시스템 관리자」 탭의 카드 가운데 운영과 직접 관련된 것은 아래와 같습니다(MCP 서버 카드는 1-4).</p><p><strong>표 1-4 어드민 콘솔 「시스템 관리자」 탭의 운영 관련 카드</strong></p><table tabindex="0"><thead><tr><th>카드</th><th>내용</th></tr></thead><tbody><tr><td>배포 프로파일</td><td>현재 프로파일과 판정 근거, 연결형 전용 기능 목록. <strong>읽기 전용</strong>입니다</td></tr><tr><td>적재 정합</td><td><code>GET /api/admin/store-consistency</code> — 메타DB 와 분석 DB(DuckDB) 사이의 적재 정합 상세</td></tr><tr><td>백업</td><td>지금 백업 · 자동 백업 설정 · 신선도 배지</td></tr><tr><td>지도 배경</td><td>지도 시각화의 배경 지도 종류와 주소. 인터넷 지도 주소를 바꾸면 「설정 다시 적용 필요」가 뜹니다 — 서버에서 <code>./setup.sh</code> 를 다시 실행해 CSP 에 반영합니다(「설치 › 2-11 지도 배경(베이스맵)」)</td></tr></tbody></table><blockquote><p><strong>주의</strong> 배포 프로파일은 <strong>화면에서 바꿀 수 없고</strong> <code>.env</code> 로만 바꿉니다. 바꾼 값은 <code>docker compose up -d</code> 로 컨테이너를 다시 만들어야 반영되며, <code>docker compose restart</code> 로는 반영되지 않습니다.</p></blockquote><h3 id="_1-4-외부-ai-에이전트-mcp-연결-설정" tabindex="-1">1-4 외부 AI 에이전트(MCP) 연결 설정 <a class="header-anchor" href="#_1-4-외부-ai-에이전트-mcp-연결-설정" aria-label="Permalink to &quot;1-4 외부 AI 에이전트(MCP) 연결 설정&quot;">​</a></h3><p>제품 서버가 직접 제공하는 <strong>외부 AI 에이전트 접속 주소</strong>입니다. Claude Code 같은 MCP 클라이언트가 <code>&lt;서버주소&gt;/api/mcp</code> 에 접속해 제품 도구를 호출합니다. 통신 방식은 Streamable HTTP 입니다. <code>POST</code> 는 initialize·JSON-RPC, <code>GET</code> 은 알림 스트림, <code>DELETE</code> 는 세션 종료이며, 세션은 <code>Mcp-Session-Id</code> 헤더로 이어집니다.</p><blockquote><p><strong>참고</strong> <strong>기본은 꺼짐</strong>입니다. 켜지 않은 서버의 <code>/api/mcp</code> 는 <code>404 mcp_disabled</code> 로만 응답합니다. 별도 프로세스로 띄우는 방식(<code>gaea-mcp</code> stdio · <code>gaea-mcp --http 5181</code>)은 이 설정과 관계없이 그대로 쓸 수 있습니다.</p></blockquote><p><strong>켜는 절차 — 어드민 콘솔</strong></p><ol><li>어드민 콘솔(<code>/admin</code>) <strong>「시스템 관리자」</strong> 탭의 <strong>「MCP 서버」</strong> 카드에서 토글을 켭니다. 설정은 DB 에 저장되고 즉시 반영되므로 <strong>API 서버 재기동은 필요 없습니다</strong>.</li><li>카드의 <strong>복사</strong> 버튼으로 엔드포인트 주소(<code>&lt;서버주소&gt;/api/mcp</code>)를 받아 사용자에게 전달합니다. 상태 배지가 <strong>켜짐 · 세션 n개 · 마지막 호출 …전 · 도구 192개</strong> 로 바뀌면 열린 것입니다.</li><li>사용자는 <strong>개인 액세스 토큰(PAT, <code>gpat_…</code>)</strong> 을 발급받아 <code>Authorization: Bearer gpat_…</code> 헤더로 붙습니다. 예: <code>claude mcp add --transport http gaea http://&lt;호스트&gt;/api/mcp --header &quot;Authorization: Bearer gpat_…&quot;</code></li><li>브라우저에서 붙는 클라이언트가 있으면 카드의 <strong>허용 오리진</strong>에 그 오리진을 적습니다(아래).</li></ol><ul><li><strong>인증은 PAT 전용</strong> — 브라우저 로그인 세션 토큰으로는 붙지 못합니다. PAT 는 제품의 「내 정보 → 개인 액세스 토큰」에서 사용자가 직접 발급합니다.</li><li><strong>라이선스</strong> — 기능 플래그 <code>agent-mcp</code>(<strong>Enterprise 전용</strong>). 미보유 배포에서는 토글을 켜도 접속이 거부됩니다.</li><li><strong>도구 수는 PAT 권한을 따라갑니다</strong> — 일반 PAT 192개, <strong>읽기 전용 PAT 81개</strong>(변이 도구 111종 제외). 주소 뒤 <code>?profile=read</code>·<code>?profile=help</code> 로 <strong>더 좁힐 수만</strong> 있고 넓힐 수는 없습니다.</li><li><strong>상태 조회</strong> — <code>GET /api/mcp/status</code> 가 <code>enabled</code>·<code>url</code>·<code>transport</code>·<code>profileDefault</code>·<code>sessions</code>·<code>lastCallAt</code>·<code>toolCount</code>·<code>entitled</code>·<code>allowedOrigins</code> 를 돌려줍니다. 설정 자체는 <code>GET/PUT /api/admin/mcp-settings</code>.</li><li><strong>감사</strong> — 설정 변경은 <code>UPDATE_MCP_SETTINGS</code> 로 기록됩니다. 도구 실행은 화면 조작과 같은 API 를 거치므로 권한 검사와 감사 기록도 같습니다. 활동 로그에는 <code>surface=&#39;mcp&#39;</code> 와 사용한 PAT 이름이 남습니다.</li></ul><p><strong>표 1-5 MCP 엔드포인트 상태코드 해독표</strong></p><table tabindex="0"><thead><tr><th>상태</th><th>코드</th><th>뜻과 조치</th></tr></thead><tbody><tr><td>401</td><td><code>unauthorized</code></td><td><code>Authorization</code> 헤더가 없거나 토큰이 유효하지 않습니다. 클라이언트 설정의 헤더를 확인합니다.</td></tr><tr><td>403</td><td><code>pat_required</code></td><td>브라우저 로그인 세션 토큰으로 붙었습니다. <strong>PAT(<code>gpat_…</code>)</strong> 로 바꿔야 합니다.</td></tr><tr><td>403</td><td><code>feature_gated</code></td><td>라이선스에 <code>agent-mcp</code> 가 없습니다(Enterprise 전용). 영업·발급 담당에게 문의합니다.</td></tr><tr><td>403</td><td><code>session_owner_mismatch</code></td><td>다른 PAT 로 만든 세션을 쓰려 했습니다. 해당 클라이언트를 다시 <code>initialize</code> 시킵니다.</td></tr><tr><td>403</td><td>Invalid Origin</td><td>허용 오리진에 없는 브라우저 클라이언트입니다. 카드의 <strong>허용 오리진</strong>에 그 오리진을 추가합니다.</td></tr><tr><td>404</td><td><code>mcp_disabled</code></td><td>기능이 꺼져 있습니다. 어드민 콘솔 「MCP 서버」 카드에서 켭니다.</td></tr><tr><td>404</td><td><code>session_not_found</code></td><td>서버가 모르는 세션입니다(재기동·유휴 30분 회수). 클라이언트를 다시 연결합니다.</td></tr><tr><td>400</td><td><code>session_required</code></td><td><code>Mcp-Session-Id</code> 헤더 없이 후속 요청이 왔습니다. 먼저 <code>POST</code> 로 <code>initialize</code> 해야 합니다.</td></tr></tbody></table><blockquote><p><strong>주의</strong> 이 엔드포인트는 <strong>평문 HTTP 로 PAT 를 받습니다</strong>. 반드시 <strong>TLS 종단 프록시(edge) 뒤</strong>에 두고, 사내망 밖으로 여는 경우 TLS 없이 노출하지 마십시오. 토큰이 새면 그 사용자의 권한 전체가 그대로 넘어갑니다.</p></blockquote><blockquote><p><strong>주의</strong> 세션 수·마지막 호출 시각은 <strong>프로세스 메모리</strong>에 있습니다 — API 서버를 재기동하면 <code>0</code> 으로 돌아갑니다(설정 자체는 DB 라 유지됩니다). <strong>다중 노드 HA</strong> 에서는 같은 세션이 같은 노드로 가도록 <strong>스티키 라우팅</strong>이 필요합니다.</p></blockquote><blockquote><p><strong>참고</strong> 이 기능이 담긴 빌드로 <strong>업그레이드한 직후</strong>에는 API 서버를 한 번 재기동해야 엔드포인트가 뜹니다. 그 뒤로는 켜고 끄는 데 재기동이 필요 없습니다.</p></blockquote><h2 id="_3-문제-해결" tabindex="-1">3. 문제 해결 <a class="header-anchor" href="#_3-문제-해결" aria-label="Permalink to &quot;3. 문제 해결&quot;">​</a></h2><p>폐쇄망 배포에는 <code>/metrics</code> 지표가 없으므로, 제품 안에서 확인할 수 있는 6가지 상태 정보로 진단합니다. 증상별 조치와 설치기 검사 메시지도 함께 싣습니다.</p><h3 id="_3-1-폐쇄망에서-쓸-수-있는-관측-표면-6종" tabindex="-1">3-1 폐쇄망에서 쓸 수 있는 관측 표면 6종 <a class="header-anchor" href="#_3-1-폐쇄망에서-쓸-수-있는-관측-표면-6종" aria-label="Permalink to &quot;3-1 폐쇄망에서 쓸 수 있는 관측 표면 6종&quot;">​</a></h3><p>장애 진단 방법은 배포 프로파일에 따라 다릅니다. <strong>connected</strong> 배포는 <code>/metrics</code>(Prometheus) 지표를 쓰고, <strong>airgap</strong> 배포는 지표가 없어 아래 6가지로 진단합니다.</p><p>현재 프로파일은 <code>grep &#39;^GAEA_DEPLOYMENT_PROFILE=&#39; .env</code> 로 확인합니다(줄이 없으면 airgap). 대부분의 고객 배포가 airgap 이므로 아래는 그 기준입니다.</p><p><strong>표 3-1 폐쇄망 관측 표면</strong></p><table tabindex="0"><thead><tr><th>#</th><th>표면</th><th>여는 법</th><th>무엇이 보이나</th></tr></thead><tbody><tr><td>①</td><td>어드민 콘솔 → 시스템</td><td>브라우저 로그인</td><td>백업 신선도 배지 · 마지막 실행 결과 · 스케줄러 가동 여부 · 배포 프로파일 · 실시간 이력 보존 정책 · 라이선스</td></tr><tr><td>②</td><td>인앱 알림(종)</td><td>어드민·워크스페이스 소유자 계정</td><td>백업이 성공에서 처음 실패로 바뀔 때 1회, 적재가 ok 에서 error 로 바뀔 때 1회 알립니다. 백업 연속 실패·라이선스 만료 임박은 <strong>운영 알림</strong>(<code>[운영]</code> 접두, 3-4)으로 알립니다</td></tr><tr><td>③</td><td><code>GET /api/ready</code></td><td><code>curl -sk https://localhost/api/ready</code></td><td><code>checks.sqlite</code>·<code>checks.duckdb</code>·<code>checks.disk</code>·<code>checks.consistency</code>, 판정 200/503 · <code>license.state</code>/<code>license.daysLeft</code>(보고 전용, 판정 무관 — 3-4)</td></tr><tr><td>④</td><td><code>docker compose ps</code></td><td><code>./gaea.sh status</code></td><td><code>healthy</code>/<code>unhealthy</code> — server 의 healthcheck 는 <code>/api/ready</code> 를 칩니다</td></tr><tr><td>⑤</td><td>컨테이너 로그</td><td><code>./gaea.sh logs server</code></td><td>백그라운드 작업 실패는 <code>opsTask</code> 값으로 검색(예: <code>[backup] 실패</code>)</td></tr><tr><td>⑥</td><td>어드민 → 접근기록(감사 로그)</td><td>브라우저</td><td><code>BACKUP_COMPLETED</code>/<code>BACKUP_FAILED</code>, 감사 체인 무결성 검증</td></tr></tbody></table><blockquote><p><strong>참고</strong> ⑤ 로그는 회전 상한(기본 50m×5)이 걸려 있습니다. 재기동을 견디는 기록은 ①(백업 저널)과 ⑥(감사 로그)뿐입니다.</p></blockquote><blockquote><p><strong>참고</strong> <strong>「시스템 사용량」의 디스크 수치는 데이터 폴더가 놓인 디스크(파일시스템) 전체입니다.</strong> 워크스페이스 운영 상태(<code>/dashboard</code>)의 「시스템 사용량」과 어드민 스토리지 상세 「디스크 여유」는 서버의 데이터 폴더(Docker 설치에서는 컨테이너 <code>/data</code> 가 마운트된 파일시스템)를 잽니다 — 다른 프로그램·다른 이미지·볼륨이 쓴 공간도 포함됩니다. 화면에도 「데이터 폴더가 있는 디스크 전체 사용량입니다 — 다른 프로그램이 쓴 공간도 포함됩니다. 스튜디오가 쓰는 양은 메타 DB · OLAP DB · 백업 항목입니다.」라고 적혀 있습니다. 스튜디오 자체 사용량은 메타 DB · OLAP DB · 백업 칸을 봅니다.</p></blockquote><h3 id="_3-2-흔한-증상과-조치" tabindex="-1">3-2 흔한 증상과 조치 <a class="header-anchor" href="#_3-2-흔한-증상과-조치" aria-label="Permalink to &quot;3-2 흔한 증상과 조치&quot;">​</a></h3><p><strong>표 3-2 증상 · 확인 · 조치</strong></p><table tabindex="0"><thead><tr><th>증상</th><th>확인</th><th>조치</th></tr></thead><tbody><tr><td>디스크 부족으로 <code>/api/ready</code> 503</td><td>표면③ <code>checks.disk</code>(임계 기본 512MB) + 호스트 <code>df -h</code></td><td>오래된 백업을 정리하고 로그 회전 설정을 확인합니다. 필요하면 볼륨을 늘리거나, 실시간 이력 보존 기간을 줄인 뒤 「지금 정리」를 누릅니다</td></tr><tr><td>백업이 조용히 멎음</td><td>표면① 「백업」 카드의 신선도 배지 · 「자동 주기 꺼짐」 경고 · 마지막 실행 결과</td><td>정지 대기(quiesce) 시간 초과가 반복되면 백업 시간대를 옮기거나 정지 대기 상한을 늘립니다. 자동 주기가 꺼져 있었으면 켜고 「지금 백업」</td></tr><tr><td>DuckDB 손상</td><td>표면③ <code>checks.duckdb.ok=false</code> 또는 <code>strict=1</code> 의 <code>checks.consistency</code></td><td>최근 정상 백업을 복원하거나(판정은 「복구 › 1-2 복원 성공 판정」), 해당 엔드포인트를 전체 재적재(full extract)합니다</td></tr><tr><td>커넥터 다운·적재 실패</td><td>인앱 알림 + 데이터소스 상세 화면의 <code>extract_status</code>/<code>extract_error</code></td><td>「연결 테스트」로 소스 접속과 자격증명을 점검합니다. 자격증명을 바꿨다면 config key 로 다시 암호화합니다</td></tr><tr><td>재기동 루프(crash loop)</td><td><code>docker compose ps</code> 가 <code>Restarting</code> 반복, 로그 반복</td><td><code>docker compose logs --tail=200</code> 으로 원인 확인 → 환경변수 오류·디스크 부족·DuckDB/SQLite 손상에 따라 대응. 5분 안에 3회 이상 재시작하면 <code>docker compose stop</code> 으로 반복을 멈추고 직접 조사</td></tr><tr><td>HA 노드가 기동하지 않음 — <code>[ha] GAEA_DATASOURCE_CONFIG_KEY 가 다른 노드와 다릅니다</code></td><td><code>./gaea.sh logs --boot</code> 의 두 지문(앞 16자)과 먼저 등록한 노드</td><td>1번 노드에서 <code>./setup.sh --export-join &lt;파일&gt;</code> → 이 노드에서 <code>./setup.sh --join &lt;파일&gt;</code>. 또는 <code>.env</code> 의 키를 1번 노드 값으로 맞춘 뒤 <code>./gaea.sh restart</code>. 전 노드 키를 의도적으로 바꿨다면 <code>app_settings</code> 의 <code>ha.config_key_fingerprint</code> 행을 지운 뒤 기동</td></tr><tr><td>사용자 IP 가 모두 로드밸런서 주소로 기록됨</td><td>감사 로그·로그인 실패 IP 가 LB 주소 하나 · <code>grep &#39;^GAEA_EDGE_REAL_IP_FROM=&#39; .env</code></td><td><code>.env</code> 의 <code>GAEA_EDGE_REAL_IP_FROM</code> 에 LB 출발지 대역(쉼표 구분 CIDR/IP)을 주고 <code>./gaea.sh restart</code>. 형식이 아닌 항목은 edge 로그에 <code>gaea-edge:</code> 경고 후 버려집니다</td></tr><tr><td>업그레이드 롤백 뒤 서버가 기동 거부 — 모르는 마이그레이션</td><td>부팅 로그의 마이그레이션 id 와 조치 문구</td><td>구 이미지가 새 스키마 위에서 기동하려는 상황입니다. 2-1 의 A(백업 복원 후 이전 버전) 또는 B(새 버전으로 전진)를 따릅니다</td></tr><tr><td>파일 올리기·대시보드 내보내기가 <code>413</code> 으로 실패</td><td>브라우저·edge 로그의 <code>413 Request Entity Too Large</code>. 요청 본문이 상한을 넘었습니다</td><td>edge(nginx)의 요청 본문 상한은 <strong>20MB</strong>(모든 경로)이고, CSV 데이터 소스 올리기(<code>/api/datasources/csv</code>)만 <strong>55MB</strong> 입니다(서버 파일 상한 50MB). 실제 상한은 서버가 경로별로 정합니다 — 대시보드 PDF·HTML 내보내기 10MB, 문서 양식 올리기 5MB 파일. 큰 파일은 나누어 올리거나 NAS 파일 소스(<code>file-sources/</code>)로 연결합니다. <code>system/nginx.conf.template</code> 을 직접 고친 값은 업그레이드 때 새 번들의 것으로 바뀝니다</td></tr><tr><td>로그인하면 「비밀번호는 맞지만 계정이 잠겨 있어요.」(<code>423</code>)</td><td>어드민 콘솔 「사용자」 목록의 <strong>잠금</strong> 배지 · 감사 로그. 연속 로그인 실패가 잠금 임계치에 닿았습니다(비밀번호가 맞을 때만 이 안내가 나오고, 틀리면 종전처럼 자격 오류입니다)</td><td>기본 정책은 <strong>10회</strong> 연속 실패 시 <strong>15분</strong> 잠금 후 자동 해제입니다. 바로 풀려면 어드민 콘솔 「사용자」에서 그 계정의 <strong>잠금 해제</strong>를 누릅니다. 임계치·지속 시간은 「보안 정책」 탭의 「계정 잠금」 카드에서 바꿉니다(임계치 0 = 잠금 끔, 지속 0 = 관리자가 풀 때까지 유지)</td></tr><tr><td>최초 관리자 비밀번호 경로가 로그에 없음</td><td><code>./gaea.sh logs</code> 는 최근 200줄만 보입니다</td><td><code>./gaea.sh logs --boot</code> 로 전체 로그의 <code>[bootstrap]</code> 줄을 찾습니다. 그래도 없으면(컨테이너 재생성) 아직 로그인 전인 계정은 재기동 한 번에 재발급됩니다</td></tr><tr><td>복원 절차 실패(이중 실패)</td><td><code>/api/ready</code>(strict 없이) 여전히 != 200, 또는 복호/추출 단계 오류</td><td>암호화 키 불일치면 <code>_PREVIOUS</code> 키 확인. 호스트가 통째로 사라졌으면 「복구」 2장 신규 호스트 DR</td></tr><tr><td>데모 켠 뒤 <code>gaea-demo-seeder</code> 가 <code>Exited (1)</code></td><td><code>docker logs gaea-demo-seeder</code> 에 <code>28P01</code>(인증 실패) · <code>gaea-demo-postgres</code> 로그에 <code>Skipping initialization</code> — 같은 호스트에 다시 설치해 이전 데모 DB 볼륨의 비밀번호가 새 <code>.env</code> 와 다릅니다</td><td><code>./demo.sh purge</code>(<code>yes</code>) → <code>./demo.sh on</code>. 데모 전용 볼륨·데모 워크스페이스만 지우며 운영 데이터(<code>gaea-data</code>)는 그대로입니다. 새 버전의 <code>./demo.sh on</code> 은 이 상황을 켜기 전에 감지해 데모 볼륨 초기화를 묻습니다</td></tr><tr><td>업그레이드 뒤 「시각화 예제」 데이터소스만 빨간색</td><td><code>docker logs gaea-server</code> 에 <code>database &quot;gaea_viz&quot; does not exist</code> — 시각화 예제 DB 는 데모 PostgreSQL 이 데이터 디렉터리를 처음 초기화할 때만 만들어지는데, 그 전 버전의 데모 볼륨을 이어받았습니다</td><td><code>./demo.sh purge</code>(<code>yes</code>) → <code>./demo.sh on</code>. 데모 볼륨을 새로 만들며 <code>gaea_viz</code> 까지 초기화합니다. 필요 없으면 그대로 두어도 다른 데모는 정상입니다</td></tr><tr><td>데모를 다시 만든 뒤 데모 PostgreSQL·MariaDB 데이터소스만 빨간색(동기화 안 됨)</td><td><code>docker logs gaea-server</code> 에 <code>password authentication failed for user &quot;gaea_reader&quot;</code>(<code>28P01</code>) · <code>Access denied for user &#39;gaea_reader&#39;</code>(<code>1045</code>) — 데모 DB 는 새 비밀번호로 초기화됐는데 데모 데이터소스 행은 지워지지 않아 옛 비밀번호를 씁니다(1.2.0 의 purge 는 서버가 꺼져 있으면 행 삭제를 건너뛰었습니다)</td><td>데이터소스 두 개의 비밀번호를 <code>.env</code> 의 <code>GAEA_DEMO_DB_PASSWORD</code> 값으로 바꿔 저장합니다. 이후 버전부터는 서버 재기동만으로 데모 데이터소스 접속 정보가 자동 갱신되고(사용자 데이터소스는 그대로), purge 는 서버가 꺼져 있어도 행을 지우며 실패하면 볼륨을 지우기 전에 멈춥니다</td></tr></tbody></table><blockquote><p><strong>참고</strong> 「백업이 조용히 멎음」은 알림 없이 진행되어 늦게 발견되기 쉽습니다. 표면①의 신선도 배지를 정기 점검 항목에 넣습니다.</p></blockquote><h3 id="_3-3-설치기-정합성-검사-—-실제-메시지" tabindex="-1">3-3 설치기 정합성 검사 — 실제 메시지 <a class="header-anchor" href="#_3-3-설치기-정합성-검사-—-실제-메시지" aria-label="Permalink to &quot;3-3 설치기 정합성 검사 — 실제 메시지&quot;">​</a></h3><p>[3/7] 단계에서 A1~A9 라벨의 검사를 순서대로 수행합니다.</p><p>검사 <strong>지점은 12개</strong>이고, <code>A8</code> 라벨은 <strong>서로 다른 세 조건</strong>에 함께 쓰입니다. 아래 표는 그 셋을 구분해 적습니다. <code>A9</code>(지도 타일)는 업그레이드기도 같은 검사를 합니다.</p><p><strong>표 3-3 정합성 검사와 실제 메시지(발췌)</strong></p><table tabindex="0"><thead><tr><th>검사</th><th>걸리는 조건</th><th>실제 메시지(발췌)</th></tr></thead><tbody><tr><td>[2/7] 필수값</td><td><code>GAEA_DATASOURCE_CONFIG_KEY</code> 미설정</td><td><code>[실패] .env 의 GAEA_DATASOURCE_CONFIG_KEY 가 비어 있습니다 — … 첫 데이터소스를 추가하는 순간 서버가 재시작 루프에 빠집니다(자격증명 봉투암호화 키).</code></td></tr><tr><td>A1</td><td>프로파일 값이 airgap/connected 밖(오타 포함)</td><td><code>[실패] GAEA_DEPLOYMENT_PROFILE 값이 잘못되었습니다(입력값: …) — airgap 또는 connected 만 허용됩니다.</code></td></tr><tr><td>A2</td><td>번들 스탬프와 <code>.env</code> 기존값 불일치, <code>--override-profile</code> 없음</td><td><code>[실패] 번들 프로파일(…)과 .env 의 GAEA_DEPLOYMENT_PROFILE(…) 이 다릅니다.</code> + <code>→ 조치: 의도한 것이면 --override-profile &lt;값&gt; 으로 다시 실행하세요.</code></td></tr><tr><td>A3</td><td>airgap 확정인데 <code>GAEA_REGISTRY_PREFIX</code> 잔존</td><td><code>[실패] airgap 프로파일인데 GAEA_REGISTRY_PREFIX 가 설정되어 있습니다 — 폐쇄망 설치는 레지스트리 참조가 없어야 합니다.</code></td></tr><tr><td>A4</td><td>airgap 인데 <code>images.tar.gz</code> 도 로드된 이미지도 없음(경량 번들 오반입)</td><td><code>[실패] airgap 프로파일인데 system/images.tar.gz 가 없고 로드된 이미지도 없습니다.</code> + <code>→ 조치: 오프라인 번들(-offline)로 다시 반입하세요.</code></td></tr><tr><td>A5</td><td>connected 인데 레지스트리 경로도 tar 도 없음</td><td><code>[실패] connected 프로파일인데 이미지를 받을 경로가 없습니다.</code> + <code>→ 조치: .env 에 GAEA_REGISTRY_PREFIX 를 설정하거나 오프라인 번들을 사용하세요.</code></td></tr><tr><td>A6</td><td>기동 전 <code>docker compose pull</code> 실패</td><td><code>[실패] 레지스트리에서 이미지를 받지 못했습니다.</code> + <code>→ 조치: GAEA_REGISTRY_PREFIX·네트워크·레지스트리 로그인 상태를 확인하세요.</code></td></tr><tr><td>A7</td><td>번들 아키텍처와 호스트 아키텍처 불일치</td><td><code>[실패] 번들 아키텍처와 이 서버의 아키텍처가 다릅니다 — 번들 …, 이 서버 ….</code> + 「네이티브 모듈이 로드되지 않아 서버가 죽습니다」 + <code>→ 조치: 빌드호스트에서 대상 아키텍처로 다시 만들어 반입하세요</code>(<code>--platform &lt;호스트&gt;</code>)</td></tr><tr><td>A8(PG 이미지)</td><td>배포 형태가 번들 PG 인데 <code>postgres:16</code> 이미지가 로컬에도 <code>pg-images.tar.gz</code> 로도 없음</td><td><code>[실패] 배포 형태가 &#39;단일 노드 + PostgreSQL(번들)&#39; 인데 postgres:16 이미지가 이 호스트에 없습니다. 폐쇄망에서는 pull 할 수 없습니다.</code> + <code>→ 조치:</code> 인터넷망에서 <code>docker pull postgres:16</code> 후 <code>docker save</code> 로 반입(다음 번들부터는 벤더에게 <code>pack-offline.sh --with-pg</code> 를 요청하면 이 절차가 없어집니다)</td></tr><tr><td>A8(PG 스탬프)</td><td><code>PG</code> 스탬프가 <code>included</code> 인데 <code>pg-images.tar.gz</code> 가 없음</td><td><code>[실패] PG 스탬프가 included 인데 system/pg-images.tar.gz 가 없습니다 — 번들이 손상되었거나 일부만 반입되었습니다.</code></td></tr><tr><td>A8(데모)</td><td><code>DEMO</code> 스탬프가 <code>included</code> 인데 <code>demo-images.tar.gz</code> 없음</td><td><code>[실패] DEMO 스탬프가 included 인데 system/demo-images.tar.gz 가 없습니다 — 번들이 손상되었거나 일부만 반입되었습니다.</code></td></tr><tr><td>A9(지도 타일)</td><td><code>MAPTILES</code> 스탬프가 <code>included</code> 인데 <code>map-tiles.tar</code> 가 없음(반대로 tar 만 있어도 중단). 풀고 난 뒤 sha256 이 스탬프와 다르면 중단</td><td><code>[실패] MAPTILES 스탬프가 included 인데 system/map-tiles.tar 가 없습니다 — 번들이 손상되었거나 일부만 반입되었습니다.</code> / <code>[실패] 푼 지도 타일의 sha256 이 스탬프와 다릅니다(기대 … · 실제 …).</code></td></tr></tbody></table><h3 id="_3-4-알림·헬스-—-제품-밖으로-나가는-신호" tabindex="-1">3-4 알림·헬스 — 제품 밖으로 나가는 신호 <a class="header-anchor" href="#_3-4-알림·헬스-—-제품-밖으로-나가는-신호" aria-label="Permalink to &quot;3-4 알림·헬스 — 제품 밖으로 나가는 신호&quot;">​</a></h3><p>3-1 의 표면 6종은 모두 <strong>로그인하거나 로그를 열어야</strong> 보입니다. 다음 세 가지 상황에서는 <strong>운영 알림</strong>이 메일·인앱 종·지표 게이지로 알립니다. 백업이 계속 실패할 때, 라이선스 만료가 가까울 때, 업그레이드 뒤 마이그레이션 실패로 서버가 기동하지 못할 때입니다. 운영 알림은 기본으로 켜져 있으며 <code>GAEA_OPS_ALERTS=0</code> 으로 끕니다. 메일은 어드민 콘솔의 메일(SMTP) 설정이나 <code>SMTP_*</code> 환경변수를 씁니다. SMTP 가 없으면 로그로만 남기며, 폐쇄망에서는 정상 동작입니다.</p><p><strong>표 3-4 운영 알림 트리거 3종</strong></p><table tabindex="0"><thead><tr><th>트리거</th><th>언제</th><th>메일</th><th>인앱 종</th><th>지표(OTLP/metrics)</th></tr></thead><tbody><tr><td>백업 연속 실패</td><td>연속 <strong>2회</strong>(<code>GAEA_OPS_ALERT_BACKUP_FAILURES</code>) 실패한 실행에서 1회. 첫 실패의 종 알림은 종전대로 별도.</td><td>제목 <code>[Gaea Studio 운영 알림] 백업이 연속 N회 실패했습니다 …</code>, 본문에 사유·마지막 성공·조치</td><td><code>[운영] 백업이 연속 N회 실패했습니다 — 최근 백업본이 없습니다</code></td><td><code>gaea_backup_last_success_ts</code>(마지막 성공 Unix 초, 없으면 0)</td></tr><tr><td>라이선스 만료 임박</td><td>유효 ≤ 14일(<code>GAEA_OPS_ALERT_LICENSE_DAYS</code>) · 평가 ≤ 7일 · 유예/무효 매일. <strong>하루 1회</strong>(재기동해도 같은 날 재발송 없음)</td><td><code>라이선스 만료 N일 전입니다</code> / <code>라이선스가 만료되었습니다 — 유예 N일 …</code></td><td>같은 문구(<code>[운영]</code> 접두)</td><td><code>gaea_license_days_left</code> · <code>gaea_license_state{state}</code></td></tr><tr><td>부팅 마이그레이션 실패</td><td>업그레이드 뒤 스키마 마이그레이션이 실패해 서버가 기동하지 못할 때(죽기 전에 1회, 재기동 루프에서는 6시간에 1회)</td><td><code>SMTP_OPS_TO</code>(없으면 <code>GAEA_BOOTSTRAP_ADMIN_EMAIL</code>) 앞으로, 환경변수 <code>SMTP_*</code> 만 사용</td><td>불가(서버가 뜨지 않음)</td><td><code>gaea_boot_migration_failed{file}</code> 1점 즉시 전송(connected + OTLP URL)</td></tr></tbody></table><table tabindex="0"><thead><tr><th>항목</th><th>내용</th></tr></thead><tbody><tr><td>수신자</td><td>플랫폼 어드민 ∪ 활성 워크스페이스 소유자(둘의 합집합 — 어드민이 한 명도 없어도 받는 사람이 생깁니다).</td></tr><tr><td>발송 실패</td><td>실패를 숨기지 않고 서버 로그에 <code>opsTask=&quot;ops-alert&quot;</code> 오류로 남기며 1회 재시도합니다. 두 번째도 실패하면 <code>final: true</code> 로 남습니다. 조회: <code>./gaea.sh logs server | grep &#39;&quot;opsTask&quot;:&quot;ops-alert&quot;&#39;</code></td></tr><tr><td><code>GET /api/ready</code> 의 라이선스</td><td>응답에 <code>license: {state, daysLeft}</code> 가 실립니다(무인증, 상태·남은 일수만). <strong>판정(200/503)에는 영향이 없습니다</strong> — 만료·무료 등급 전환은 기능 잠금이지 서비스 정지가 아니므로, 외부 모니터링은 이 필드를 <strong>별도 규칙</strong>으로 봅니다(예: <code>license.daysLeft &lt; 7</code> 경고).</td></tr><tr><td>지표 게이지</td><td><code>GAEA_METRICS=1</code> 이면 <code>/metrics</code> 에, <code>GAEA_OTEL_EXPORT_URL</code> 이 설정된 connected 배포면 OTLP 로 자동 전송됩니다. 폐쇄망(airgap)은 지표 없이 메일·종·로그만 씁니다.</td></tr></tbody></table><blockquote><p><strong>주의</strong> 운영 알림은 실제로 받는 사람에게 도착해야 의미가 있습니다. 설치 직후 어드민 콘솔 → 메일(SMTP) 설정의 <strong>테스트 발송</strong>으로 메일 경로를 한 번 확인해 두세요. SMTP 가 없는 폐쇄망은 인앱 종과 <code>docker compose ps</code> 의 <code>unhealthy</code>(3-1 ④)가 1차 신호입니다.</p></blockquote>',67)])])}const u=d(r,[["render",a]]);export{h as __pageData,u as default};
